{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "inputs"
  },
  "title": {
    "text": "Minutes of shadow per park",
    "subtitle": "Click a bar to pick a park"
  },
  "transform": [
    {
      "calculate": "['Existing', 'Towers removed', 'Height cap'][datum.__input__]",
      "as": "scenario_name"
    },
    {
      "calculate": "datum.__input__ === 0 ? datum.mean_min : null",
      "as": "existing_rows"
    },
    {
      "calculate": "datum.__input__ === 1 ? datum.mean_min : null",
      "as": "removed_rows"
    },
    {
      "calculate": "datum.__input__ === 2 ? datum.mean_min : null",
      "as": "capped_rows"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "existing_rows",
          "as": "existing"
        },
        {
          "op": "max",
          "field": "removed_rows",
          "as": "removed"
        },
        {
          "op": "max",
          "field": "capped_rows",
          "as": "capped"
        }
      ],
      "groupby": [
        "park"
      ]
    },
    {
      "filter": "isValid(datum.existing) && isValid(datum.removed) && isValid(datum.capped)"
    },
    {
      "calculate": "datum.existing - datum.removed",
      "as": "gain_removed"
    },
    {
      "calculate": "datum.existing - datum.capped",
      "as": "gain_capped"
    },
    {
      "calculate": "min(datum.existing, datum.removed, datum.capped)",
      "as": "lowest"
    },
    {
      "calculate": "max(datum.existing, datum.removed, datum.capped)",
      "as": "highest"
    }
  ],
  "hconcat": [
    {
      "width": 300,
      "height": {
        "step": 13
      },
      "encoding": {
        "y": {
          "field": "park",
          "type": "nominal",
          "sort": {
            "field": "gain_removed",
            "op": "max",
            "order": "descending"
          },
          "title": null
        },
        "opacity": {
          "condition": {
            "param": "pick",
            "empty": true,
            "value": 1
          },
          "value": 0.25
        }
      },
      "layer": [
        {
          "transform": [
            {
              "filter": "datum.__input__ === 0"
            }
          ],
          "mark": {
            "type": "rule",
            "color": "#9ca3af",
            "strokeWidth": 2
          },
          "encoding": {
            "x": {
              "field": "lowest",
              "type": "quantitative",
              "title": "Mean shadow (minutes)"
            },
            "x2": {
              "field": "highest"
            }
          }
        },
        {
          "mark": {
            "type": "point",
            "filled": true,
            "size": 60,
            "opacity": 1,
            "tooltip": true
          },
          "encoding": {
            "x": {
              "field": "mean_min",
              "type": "quantitative"
            },
            "color": {
              "field": "scenario_name",
              "type": "nominal",
              "scale": {
                "domain": [
                  "Existing",
                  "Towers removed",
                  "Height cap"
                ],
                "range": [
                  "#2a9d8f",
                  "#e76f51",
                  "#6a4c93"
                ]
              },
              "legend": {
                "title": "Scenario",
                "orient": "bottom"
              }
            }
          }
        }
      ]
    },
    {
      "width": 220,
      "height": {
        "step": 13,
        "for": "position"
      },
      "transform": [
        {
          "filter": "datum.__input__ === 0"
        },
        {
          "fold": [
            "gain_removed",
            "gain_capped"
          ],
          "as": [
            "gain_key",
            "gain"
          ]
        },
        {
          "calculate": "datum.gain_key === 'gain_removed' ? 'Towers removed' : 'Height cap'",
          "as": "what_if"
        }
      ],
      "params": [
        {
          "name": "pick",
          "select": {
            "type": "point",
            "fields": [
              "park"
            ]
          }
        }
      ],
      "mark": {
        "type": "bar",
        "tooltip": true,
        "cursor": "pointer"
      },
      "encoding": {
        "y": {
          "field": "park",
          "type": "nominal",
          "sort": {
            "field": "gain_removed",
            "op": "max",
            "order": "descending"
          },
          "axis": null
        },
        "yOffset": {
          "field": "what_if",
          "sort": [
            "Towers removed",
            "Height cap"
          ]
        },
        "x": {
          "field": "gain",
          "type": "quantitative",
          "title": "Sun gained (minutes)"
        },
        "color": {
          "field": "what_if",
          "type": "nominal",
          "scale": {
            "domain": [
              "Existing",
              "Towers removed",
              "Height cap"
            ],
            "range": [
              "#2a9d8f",
              "#e76f51",
              "#6a4c93"
            ]
          },
          "legend": {
            "title": "Scenario",
            "orient": "bottom"
          }
        },
        "opacity": {
          "condition": {
            "param": "pick",
            "empty": true,
            "value": 1
          },
          "value": 0.25
        }
      }
    }
  ]
}
